const CARD_IMAGE_SIZES = "(max-width: 700px) 44vw, (max-width: 1180px) 30vw, 23vw";
function responsivePhotoSet(src) {
  const photo = responsivePhotos["/" + src.replace(/^\//, "")];
  return photo ? photo[1].map(width => `/assets/images/responsive/${photo[0]}-${width}.webp ${width}w`).join(", ") : "";
}
function responsivePhotoAttributes(src, sizes = CARD_IMAGE_SIZES) {
  const srcset = responsivePhotoSet(src);
  return srcset ? `srcset="${srcset}" sizes="${sizes}"` : "";
}
const photoChanges = new WeakMap();
function setResponsivePhoto(image, src, sizes = image.sizes || CARD_IMAGE_SIZES, animate = false) {
  const change = {};
  photoChanges.set(image, change);
  image.getAnimations?.().forEach(animation => animation.cancel());
  image.sizes = sizes;
  const srcset = responsivePhotoSet(src);
  if (srcset) image.srcset = srcset;
  else image.removeAttribute("srcset");
  image.src = src;
  // The browser keeps the current picture while the next one decodes. Never
  // fade to an empty frame, and a late load cannot replace a newer selection.
  if (animate && image.decode && !matchMedia("(prefers-reduced-motion: reduce)").matches) {
    image.decode().then(() => {
      if (photoChanges.get(image) === change) image.animate?.([{opacity: .7}, {opacity: 1}], {duration: 180});
    }).catch(() => {});
  }
}

function setupGallerySwipe(stage, onSwipe) {
  if (!stage) return;
  let start = null;
  let suppressClickUntil = 0;
  stage.addEventListener("pointerdown", event => {
    if (!event.isPrimary || event.pointerType === "mouse" || event.target.closest("button, a")) {
      start = null;
      return;
    }
    start = {id: event.pointerId, x: event.clientX, y: event.clientY};
  });
  stage.addEventListener("pointercancel", () => { start = null; });
  stage.addEventListener("pointerup", event => {
    if (!start || event.pointerId !== start.id) return;
    const dx = event.clientX - start.x;
    const dy = event.clientY - start.y;
    start = null;
    if (Math.abs(dx) < 48 || Math.abs(dx) < Math.abs(dy) * 1.5) return;
    suppressClickUntil = performance.now() + 400;
    onSwipe(dx < 0 ? 1 : -1);
  });
  stage.addEventListener("click", event => {
    if (performance.now() < suppressClickUntil) {
      event.preventDefault();
      event.stopImmediatePropagation();
    }
  }, true);
}

